const deckEl = document.querySelector('.deck');
const handEl = document.querySelector('#hand');
const deck = [...deckEl.querySelectorAll('playing-card')];
function shuffleInPlace(cards) {
  for (let i = cards.length - 1; i >= 1; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [cards[i], cards[j]] = [cards[j], cards[i]];
  }
}
document.querySelector('#draw-hand').addEventListener('click', () => {
  const copy = [...deck];
  shuffleInPlace(copy);
  const handCards = copy.slice(0, 5);
  handCards.forEach((card) => card.cloneNode(true));
  handCards.forEach((card) => card.removeAttribute('id'));
  handEl.replaceChildren(...handCards);
});

